custom_scss:
/* Knowledge-wiki touches — Quartz variables only */
.kg-hero {
  border: 1px solid var(--gray);
  border-left: 4px solid var(--tertiary);
  background: var(--lightgray);
  border-radius: 8px;
  padding: 1.25rem 1.5rem;
  margin: 1.5rem 0 2.25rem;
}
.kg-hero .kg-kicker {
  font-family: var(--codeFont, 'IBM Plex Mono', monospace);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--tertiary);
  margin-bottom: 0.5rem;
}
.kg-hero h1, .kg-hero h2 {
  color: var(--dark);
  margin: 0 0 0.5rem;
  letter-spacing: -0.01em;
}
.kg-hero p {
  color: var(--darkgray);
  margin: 0;
  max-width: 62ch;
}
a {
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--tertiary) 55%, transparent);
  text-underline-offset: 3px;
  text-decoration-thickness: 1px;
  transition: color 150ms ease;
}
a:hover { color: var(--tertiary); }
blockquote {
  border-left: 3px solid var(--secondary);
  background: var(--lightgray);
  padding: 0.75rem 1.25rem;
  border-radius: 0 8px 8px 0;
  color: var(--darkgray);
  margin: 1.5rem 0;
}
code {
  background: var(--lightgray);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
hr { border-color: var(--gray); }
